(*
  Semantic conflict report (not resolved silently):
  1) Req.4/K4 says "VFDRun=TRUE and any non-zero code -> TripOutput immediately", but Req.1 and LTL C1 exclude 16#0001 from trip.
     This FB follows Req.1/C1: 16#0001 is treated as light fault only.
  2) LTL C2 says G(TripOutput -> !VFDRun), but K1/K4/C1 require TripOutput TRUE in the same scan when VFDRun can still be TRUE.
     VFDRun is a read-only input; this FB cannot write it. Immediate trip/latch is implemented and the conflict is reported here.
  3) C10 requires no trip/alarm and Status=16#0000 in the first cycle. If a heavy fault is already present at power-up, immediate K1 conflicts.
     This FB forces initial outputs on the first scan and processes faults from the next scan.
*)
FUNCTION_BLOCK FB_S10
VAR_INPUT
    VFDFaultCode : WORD;
    VFDRun : BOOL;
    ResetBtn : BOOL;
END_VAR
VAR_OUTPUT
    AlarmLamp : BOOL;
    TripOutput : BOOL;
    Status : WORD;
END_VAR
VAR
    FirstScan : BOOL := TRUE;
    ResetBtnLast : BOOL := FALSE;
    TripLatched : BOOL := FALSE;
    LatchedFaultCode : WORD := 16#0000;
    ResetPulse : BOOL;
    NoFault : BOOL;
    LightFault : BOOL;
    HeavyFault : BOOL;
    RunNonLightFault : BOOL;
    TripCondition : BOOL;
END_VAR

IF FirstScan THEN
    TripOutput := FALSE;
    AlarmLamp := FALSE;
    Status := 16#0000;
    TripLatched := FALSE;
    LatchedFaultCode := 16#0000;
    ResetBtnLast := ResetBtn;
    FirstScan := FALSE;
ELSE
    ResetPulse := ResetBtn AND NOT ResetBtnLast;
    ResetBtnLast := ResetBtn;

    NoFault := (VFDFaultCode = 16#0000);
    LightFault := (VFDFaultCode = 16#0001);
    HeavyFault := (VFDFaultCode = 16#0002) OR (VFDFaultCode = 16#0003);
    RunNonLightFault := VFDRun AND (VFDFaultCode <> 16#0000) AND (VFDFaultCode <> 16#0001);
    TripCondition := HeavyFault OR RunNonLightFault;

    IF TripLatched THEN
        TripOutput := TRUE;
        AlarmLamp := TRUE;

        IF TripCondition THEN
            LatchedFaultCode := VFDFaultCode;
        END_IF;

        Status := LatchedFaultCode;

        IF ResetPulse AND NoFault THEN
            TripLatched := FALSE;
            LatchedFaultCode := 16#0000;
            TripOutput := FALSE;
            AlarmLamp := FALSE;
            Status := 16#0000;
        END_IF;
    ELSE
        IF TripCondition THEN
            TripLatched := TRUE;
            LatchedFaultCode := VFDFaultCode;
            TripOutput := TRUE;
            AlarmLamp := TRUE;
            Status := VFDFaultCode;
        ELSIF LightFault THEN
            TripOutput := FALSE;
            AlarmLamp := TRUE;
            Status := 16#0001;
        ELSE
            TripOutput := FALSE;
            AlarmLamp := FALSE;
            Status := 16#0000;
        END_IF;
    END_IF;
END_IF;
END_FUNCTION_BLOCK
